using Engine.Actions;
using Newtonsoft.Json;

namespace Engine.Models;

public class GameItem
{
    public enum ItemCategory
    {
        Miscellanous,
        Weapon,
        Consumable
    }
    [JsonIgnore]
    public ItemCategory Category {get; }
    public int ItemTypeId { get;}
    [JsonIgnore]
    public string Name { get;}
    [JsonIgnore]
    public int Price { get;}
    [JsonIgnore]
    public bool IsUnique {get;}
    [JsonIgnore]
    public IAction? Action {get; set;}

    public GameItem(ItemCategory category, int itemTypeId, string name, int price, bool isUnique = false, IAction? action = null)
    {
        Category = category;
        ItemTypeId = itemTypeId;
        Name = name;
        Price = price;
        IsUnique = isUnique;
        Action = action;
    }
    public void PerformAction(LivingEntity actor, LivingEntity target)
    {
        Action?.Execute(actor, target);
    }

    public GameItem Clone()
    {
        // The clone gets its own Action. Sharing one Action between clones would let
        // every holder of the same item type receive each other's OnActionPerformed messages.
        GameItem clone = new GameItem(Category, ItemTypeId, Name, Price, IsUnique);
        clone.Action = Action?.Clone(clone);
        return clone;
    }
}
